upserted as (
 insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status)
 select t.id,s.objective_code,s.indicator_name,
        'Official Thai indicator wording: '||s.indicator_name,
        s.sequence_no,'active'
 from seed s
 join public.learning_subjects sub on sub.code='FOREIGN-LANGUAGES'
 join public.learning_skills sk on sk.subject_id=sub.id
 join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code
 on conflict(topic_id,code) do update
 set name=excluded.name,description=excluded.description,
     sequence_no=excluded.sequence_no,status='active',updated_at=now()
 returning id,topic_id,code
)
insert into public.learning_objective_alignments(
 objective_id,curriculum_id,grade_level_id,sequence_no,required,indicator_classification,notes
)
select u.id,c.id,g.id,s.sequence_no,(s.priority='must_know'),s.priority,
       'Official indicator: '||s.official_indicator_code||'. OBEC 2021 priority classification.'
from seed s
join public.learning_subjects sub on sub.code='FOREIGN-LANGUAGES'
join public.learning_skills sk on sk.subject_id=sub.id
join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code
join upserted u on u.topic_id=t.id and u.code=s.objective_code
join public.learning_curricula c on c.code='TH-BASIC-CORE-2008-2017' and c.status='active'
join public.learning_grade_levels g on g.curriculum_id=c.id and g.code=s.grade_code and g.status='active'
on conflict(objective_id,curriculum_id,grade_level_id) do update
set sequence_no=excluded.sequence_no,required=excluded.required,
    indicator_classification=excluded.indicator_classification,
    notes=excluded.notes,updated_at=now();